import{_ as p,a0 as o,w as u,s as a,ao as d,I as s,x as n,a1 as r,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"每日Ubuntu小技巧-使用Windows共享打印机进行打印 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧-使用Windows共享打印机进行打印 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧-使用Windows共享打印机进行打印 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧-使用Windows共享打印机进行打印 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/Daily Ubuntu Tips – Print From Shared Windows Printers","title":"每日Ubuntu小技巧-使用Windows共享打印机进行打印","tag":"201312","desc":""},"relativePath":"201312/Daily Ubuntu Tips – Print From Shared Windows Printers.md","filePath":"[post].md"}'),w={name:"201312/Daily Ubuntu Tips – Print From Shared Windows Printers.md"};function l(g,t,b,m,T,W){const i=o("Link");return u(),a("div",null,[t[11]||(t[11]=d(`<h1 id="每日ubuntu小技巧-使用windows共享打印机进行打印" tabindex="-1">每日Ubuntu小技巧-使用Windows共享打印机进行打印 <a class="header-anchor" href="#每日ubuntu小技巧-使用windows共享打印机进行打印" aria-label="Permalink to “每日Ubuntu小技巧-使用Windows共享打印机进行打印”">​</a></h1><p>对于那些既有Windows电脑又有Ubuntu电脑但却只有一台打印机的用户，这篇博文向你展示如何在Windows中共享一个打印机，并允许Ubuntu使用它来打印。</p><p>几乎所有的打印机都默认支持Windows系统。许多打印机生产商都为Windows生产打印机，但为包括Ubuntu在内的Linux系统生产的并不多。所以，假如你有一台支持Windows的打印机，你可以在Windows机器上分享它，然后让其它系统来使用它来打印。</p><p>在几年之前，我遇到了这个问题，那时大多数打印机生产商不支持Linux系统。我有一台老式的只支持Windows和Mac OS X但却不支持Linux的打印机。（译注：除非是特别冷门的打印机，现在一般都可以在Linux进行打印操作了。在译者看来，本文的理由不成立，不过做法成立。）</p><p>我在我的Windows机器上安装了打印机驱动，然后它就可以很好的工作咯。我的Windows机器使用它来打印非常好，但是我的Ubuntu却无法使用它来打印，因为打印机并不支持LAN接口。</p><p>所以，我在Windows上共享该打印机，然后我的Ubuntu机器就可以使用合适的字体和风格进行打印咯。假如你也遇到类似的情景，你可以按照下面的指导来操作。</p><p>首先，登入Windows，右击你要共享的打印机，然后点击‘<strong>Printer properties（打印机属性）</strong>’</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/printersharingubuntu.png" alt=""></p><p>接着，选择“<strong>Sharing（共享）</strong>”标签页，勾选‘<strong>Share this printer（共享这台打印机）</strong>’复选框来共享。记住共享打印机的名字，因为你要使用这个共享名来连接这台打印机。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/printersharingubuntu1.png" alt=""></p><p>最后，以管理员权限运行命令行终端，运行以下命令以便于文件和打印机可以通过防火墙实现共享。</p><pre><code>netsh advfirewall firewall set rule group=&quot;File and Printer Sharing&quot; new enable=Yes
</code></pre><p>接着，登入Ubuntu中，选择顶部面板右边的<strong>齿轮</strong>，然后选择<strong>系统设置...</strong></p><p>系统设置打开后，选择打印机，然后点击<strong>添加</strong>。当跳出来一个窗口让你选择设备时，选择‘<strong>Windows Printer via SAMBA（使用SAMBA的Windows打印机）</strong>’。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/printersharingubuntu2.png" alt=""></p><p>键入Windows电脑的IP地址或者主机名，后面接着键入共享的打印机名。你可能需要键入你的windows验证信息（用户名和密码）。点击浏览来验证你是否可以看到打印机，当你完成这些后，就可以点击下一步继续。</p><p>接着，选择打印机品牌和型号。假如你在列表中看不到特定的型号，选择一个最接近它的然后继续。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/printersharingubuntu3.png" alt=""></p><p>以上这些都搞定了之后，你的打印机就已安装好，可以使用喽。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/printersharingubuntu4.png" alt=""></p><p>好好享受吧！</p><hr>`,22)),s("p",null,[t[1]||(t[1]=n("via: ",-1)),r(i,{href:"http://www.liberiangeek.net/2013/11/daily-ubuntu-tips-print-from-shared-windows-printers/"},{default:e(()=>[...t[0]||(t[0]=[n("http://www.liberiangeek.net/2013/11/daily-ubuntu-tips-print-from-shared-windows-printers/",-1)])]),_:1})]),s("p",null,[t[4]||(t[4]=n("译者：",-1)),r(i,{href:"https://github.com/Linux-pdz"},{default:e(()=>[...t[2]||(t[2]=[n("Linux-pdz",-1)])]),_:1}),t[5]||(t[5]=n(" 校对：",-1)),r(i,{href:"https://github.com/carolinewuyan"},{default:e(()=>[...t[3]||(t[3]=[n("Caroline",-1)])]),_:1})]),s("p",null,[t[8]||(t[8]=n("本文由 ",-1)),r(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原创翻译，",-1)),r(i,{href:"http://linux.cn/"},{default:e(()=>[...t[7]||(t[7]=[n("Linux中国",-1)])]),_:1}),t[10]||(t[10]=n(" 荣誉推出",-1))])])}const P=p(w,[["render",l]]);export{x as __pageData,P as default};
